def cancelingStampsProofStrip(readings):
    a=readings
    out=[]
    for x in a:
        if out and out[-1]==x: out.pop()
        else: out.append(x)
    return out


java
class Solution {
  public int[] cancelingStampsProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){if(!out.isEmpty()&&out.get(out.size()-1)==x)out.remove(out.size()-1);else out.add(x);}}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
